import * as L from 'leaflet';

import { showModal } from '@ui-kit/Modal';

import ClearRouteModal from './ClearRouteModal';

export interface ILayerWithName {
  layer: L.Layer;
  name?: string;
}

export const clearRoute = async (id: number): Promise<void> => {
  return new Promise((resolve) => {
    showModal({
      title: 'Очистка маршрута',
      children: (clos: () => void) => (
        <ClearRouteModal
          id={id}
          onConfirm={() => {
            resolve();
            clos();
          }}
        />
      ),
    });
  });
};
