import { showModal } from '@ui-kit/Modal';

import JoinTracksModal, { IJoinTracksModalProps } from './JoinTracksModal';

export const selectTrackForJoin = async ({
  ...props
}: Omit<IJoinTracksModalProps, 'onConfirm'>): Promise<IJoinTracksModalProps['currentLine']> => {
  return new Promise((resolve) => {
    showModal({
      title: 'Объединение треков',
      children: (clos: () => void) => (
        <JoinTracksModal
          {...props}
          onConfirm={(res) => {
            resolve(res);
            clos();
          }}
        />
      ),
    });
  });
};
