import React from 'react';

import ChevronBarRight from '@pohodnik/icons/svg/Chevrons/ChevronBarRight';
import GeoAlt from '@pohodnik/icons/svg/Geo/GeoAlt';
import Bezier2 from '@pohodnik/icons/svg/Graphics/Bezier2';
import DashCircleDotted from '@pohodnik/icons/svg/Signs/DashCircleDotted';

import { formatDistance } from '@helpers/formatHelper';
import PohButton, { ButtonSize } from '@ui-kit/Button';

import RoutesEditorSidebarHeaderBadge from './RoutesEditorSidebarHeaderBadge';
import { useRoutesDispatch, useRoutesSelector } from '../../../@store/hooks';
import { setFilters, toggleSidebar } from '../../../@store/route.slice';
import { RouteObjectType } from '../../../@types/routes.types';

const RoutesEditorSidebarFooter: React.FC = () => {
  const { filters, routeObjects } = useRoutesSelector((state) => state.route);
  const dispatch = useRoutesDispatch();

  let distanceOn = 0;
  let distanceOff = 0;

  routeObjects.forEach((ro) => {
    if (ro.type !== RouteObjectType.Line) return;
    if (ro.is_in_distance) distanceOn += ro.distance;
    if (!ro.is_in_distance) distanceOff += ro.distance;
  });

  return (
    <footer className="px-3 py-2 bg-light d-flex justify-content-between align-items-center">
      <strong>
        <PohButton icon={true} onClick={() => dispatch(toggleSidebar())}>
          <ChevronBarRight />
        </PohButton>
      </strong>
      <aside className="d-flex align-items-center">
        <small className="me-3 d-flex flex-column" style={{ lineHeight: 0.9 }}>
          {filters.showLines && distanceOn > 0 && <strong>{formatDistance(distanceOn)}</strong>}
          {filters.showNotInDistance && distanceOff > 0 && (
            <small className="text-muted">
              <s>{formatDistance(distanceOff)}</s>
            </small>
          )}
        </small>
        <PohButton
          icon={true}
          size={ButtonSize.Small}
          active={filters.showPoints}
          onClick={() => dispatch(setFilters({ ...filters, showPoints: !filters.showPoints }))}
          className="position-relative"
        >
          <GeoAlt />
          <RoutesEditorSidebarHeaderBadge active={filters.showPoints}>
            {routeObjects.reduce((acc, ro) => acc + (ro.type === RouteObjectType.Point ? 1 : 0), 0)}
          </RoutesEditorSidebarHeaderBadge>
        </PohButton>
        <PohButton
          icon={true}
          size={ButtonSize.Small}
          className="ms-1 position-relative"
          active={filters.showLines}
          onClick={() => dispatch(setFilters({ ...filters, showLines: !filters.showLines }))}
        >
          <Bezier2 />
          <RoutesEditorSidebarHeaderBadge active={filters.showLines}>
            {routeObjects.reduce((acc, ro) => acc + (ro.type === RouteObjectType.Line ? 1 : 0), 0)}
          </RoutesEditorSidebarHeaderBadge>
        </PohButton>
        <PohButton
          icon={true}
          size={ButtonSize.Small}
          className="ms-1  position-relative"
          active={filters.showNotInDistance}
          onClick={() =>
            dispatch(setFilters({ ...filters, showNotInDistance: !filters.showNotInDistance }))
          }
        >
          <DashCircleDotted />
          <RoutesEditorSidebarHeaderBadge active={filters.showNotInDistance}>
            {routeObjects.reduce((acc, ro) => acc + (ro.is_in_distance ? 0 : 1), 0)}
          </RoutesEditorSidebarHeaderBadge>
        </PohButton>
      </aside>
    </footer>
  );
};

export default RoutesEditorSidebarFooter;
