/* eslint-disable no-async-promise-executor */

import { success } from '@helpers/notificationHelper';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';

import { getLeafletMapManager } from '../@managers/leafletMap.manager';
import { IRouteObject, RouteObjectType } from '../@types/routes.types';

export const deleteRouteObjectWithConfirm = async (
  routeObject: IRouteObject,
  withoutConfirm = false,
): Promise<void> => {
  return new Promise<void>(async (resolve, reject) => {
    const accept =
      withoutConfirm ||
      (await confirmModal2(
        `Точно удалить ${routeObject.type === RouteObjectType.Line ? 'путь' : 'точку'}\n«${routeObject.name}»?`,
      ));
    if (accept) {
      getLeafletMapManager().removeObjectById(routeObject.id);
      !withoutConfirm && success('Удалено');
      resolve();
    } else {
      reject();
    }
  });
};
