import React from 'react';

import 'leaflet/dist/leaflet.css';
import { MapContainer } from 'react-leaflet';

import { defaultMapCoordinates, defaultMapZoom } from '@helpers/leafletHelper';

import ControlEditor from './components/ControlEditor';
import InitForMap from './components/InitForMap';
import MapTypesControl from './components/MapTypesControl';
import RouteObjects from './components/RouteObjects';
import styles from './styles.module.less';
import { useRoutesSelector } from '../../../@store/hooks';

interface IRouteEditorMapProps {}

const RouteEditorMap: React.FC<IRouteEditorMapProps> = () => {
  const { currentMapType } = useRoutesSelector((state) => state.route);

  if (!currentMapType) return <div> has no currentMapType</div>;
  return (
    <MapContainer
      center={defaultMapCoordinates}
      zoom={defaultMapZoom}
      scrollWheelZoom={true}
      className={styles.routeEditorMap}
      attributionControl={false}
    >
      <InitForMap />
      <ControlEditor position="topright" />
      <RouteObjects />
      <MapTypesControl />
    </MapContainer>
  );
};

export default RouteEditorMap;
