import * as L from 'leaflet';

import { showModal } from '@ui-kit/Modal';

import ImportGPXModal from './ImportGPXModal';

export interface ILayerWithName {
  layer: L.Layer;
  name?: string;
}

export const importGpxModal = async (): Promise<ILayerWithName[]> => {
  return new Promise((resolve) => {
    showModal({
      title: 'Import GPX',
      children: (clos: () => void) => (
        <ImportGPXModal
          onChange={(res) => {
            resolve(res);
            clos();
          }}
        />
      ),
    });
  });
};
