import React from 'react';

import { formatAltitude } from '@helpers/formatHelper';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';

import { getRoutesVariants, IGraphhopperResponsePath } from './autoRoute.service';
import { formatDistance } from '../../../@classes/XneekPolylineEditor/helpers';

export interface IRouteAutoProps {
  points: Array<[number, number, number] | [number, number]>;
  onSave: (newPoints: Array<[number, number, number]>) => void;
}

function formatTime(ms: number) {
  const min = ms / 1000 / 60;
  return min < 60
    ? `${min.toFixed()}\u00a0мин.`
    : `${Math.floor(min / 60)}\u00a0ч. ${Math.floor(min % 60)}\u00a0мин.`;
}

const RouteAuto: React.FC<IRouteAutoProps> = ({ points, onSave }) => {
  const [isLoading, setIsLoading] = React.useState(false);
  const [err, setErr] = React.useState<Error>();
  const [variants, setVariants] = React.useState<IGraphhopperResponsePath[] | null>(null);

  React.useEffect(() => {
    const start = async () => {
      try {
        setIsLoading(true);

        const res = await getRoutesVariants(
          points.map((p) => [p[0], p[1]]),
          { optimize: true, vehicle: 'foot' },
        );

        if (
          !res ||
          (res.paths && res.paths.length === 0) ||
          res.paths[0].points.coordinates.length < 3
        ) {
          throw new Error(
            'Не удалось построить маршрут. Попробуйте более точно указать точки маршрута',
          );
        }

        setVariants(res.paths);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };
    start();
  }, []);

  if (isLoading) return <PohLoader />;

  if (variants && variants.length > 0) {
    return (
      <PohList
        data={variants.map((data) => {
          return {
            key: data.weight,
            content: (
              <div className="d-flex" style={{ gap: 8 }}>
                <span>
                  <small className="text-muted">Протяженность:</small>
                  <strong>{formatDistance(data.distance)}</strong>
                </span>
                <span>
                  <small className="text-muted">Время в пути:</small>
                  <strong>{formatTime(data.time)}</strong>
                </span>
                <span>
                  <small className="text-muted">Подъем:</small>
                  <strong>{formatAltitude(data.ascend)}</strong>
                </span>
                <span>
                  <small className="text-muted">Спуск:</small>
                  <strong>{formatAltitude(data.descend)}</strong>
                </span>
              </div>
            ),
            action: true,
            onClick: () => {
              onSave(data.points.coordinates.map(([lon, lat, alt]) => [lat, lon, alt]));
            },
          };
        })}
      />
    );
  }

  return <p>{err?.message}</p>;
};

export default RouteAuto;
