import * as L from 'leaflet';

import { distanceFromPointToLine } from './helpers';
import styles from './styles.module.less';
import { XneekPolylineTicks } from '../XneekPolylineTicks/XneekPolylineTicks';

const defaultLineOptions: L.PathOptions = {
  color: 'red',
  weight: 1,
};

export enum XneekPolylineEditorState {
  Idle,
  Started,
  Drawing,
  Editing,
}

const mapClassName = 'xneek-map-e';
const auxiliaryLineClassName = 'xneek-auxiliaryLine';

interface IXneekPolylineEditorOptions {
  mainLineOptions: L.PathOptions;
  auxiliaryLineOptions: L.PathOptions;
  drawingLineOptions: L.PathOptions;
}

interface IChangeHandlerAttributes {
  points: L.LatLng[];
  marker: L.Marker;
  distance: number;
  index: number;
  reason: string;
}

const defaultOptions = {
  mainLineOptions: { ...defaultLineOptions, opacity: 1 },
  auxiliaryLineOptions: {
    ...defaultLineOptions,
    opacity: 0.1,
    weight: 16,
    color: 'white',
    className: auxiliaryLineClassName,
  },
  drawingLineOptions: { ...defaultLineOptions, dashArray: [5, 7], interactive: false },
};

export class XneekPolylineEditor {
  private readonly map: L.Map;
  private readonly options: IXneekPolylineEditorOptions = defaultOptions;

  private markers: L.Marker[] = [];

  private markersGroup = L.layerGroup();
  private polylineGroup = L.layerGroup();
  private measuresGroup = L.layerGroup();

  private isDrawing = false;
  private isFromEnd = true;

  private hasChanges = false;

  private isLastOnLine = false;

  private polyline: L.Polyline;
  private polyline2: L.Polyline;
  private potentialPolyline: L.Polyline;

  private onChangeHandler: ((attrs: IChangeHandlerAttributes) => void) | undefined;
  private onSaveHandler: ((latlngs: L.LatLng[], distance: number) => void) | undefined;

  private onStateChangeHandler: ((state: XneekPolylineEditorState) => void) | undefined;
  private onPointContextmenuHandler:
    | ((
        e: L.LeafletEvent,
        callbacks: {
          remove: () => void;
          setLatLng: (latLng: L.LatLng) => void;
        },
      ) => void)
    | undefined;

  private ticks: XneekPolylineTicks;

  private redrawDebounce: ReturnType<typeof setTimeout> | null = null;

  private asyncPointUpdater?: (points: L.LatLng[]) => Promise<L.LatLng[]>;
  private asyncPointDebounce?: number = 600;
  private asyncPointUpdaterTimeout: ReturnType<typeof setTimeout> | null = null;

  state: XneekPolylineEditorState = XneekPolylineEditorState.Idle;

  constructor(map: L.Map, options: Partial<IXneekPolylineEditorOptions> = {}) {
    this.map = map;
    this.options = {
      ...this.options,
      ...options,
    };

    this.polyline = L.polyline([], this.options.mainLineOptions);
    this.polyline2 = L.polyline([], this.options.auxiliaryLineOptions);
    this.potentialPolyline = L.polyline([], this.options.drawingLineOptions);
    this.ticks = new XneekPolylineTicks(map);
  }

  private init() {
    this.polyline.on('mousedown', this.handleMouseDown);
    this.polyline2.on('mousedown', this.handleMouseDown);
    this.polyline.on('click', this.handleMouseDown);
    this.polyline2.on('click', this.handleMouseDown);

    this.map.on('click', this.handleMapClick);
    this.map.on('mousemove', this.handleMapMouseMove);
    this.map.on('mousedown', this.handleMapMouseDown);

    this.polyline.addTo(this.polylineGroup);
    this.polyline2.addTo(this.polylineGroup);
    this.potentialPolyline.addTo(this.polylineGroup);

    this.polyline.bringToFront();
    this.polyline2.bringToFront();

    this.measuresGroup.addTo(this.map);
    this.polylineGroup.addTo(this.map);
    this.markersGroup.addTo(this.map);
    this.ticks.init(this.measuresGroup);

    L.DomUtil.addClass(this.getMapContainerNode(), mapClassName);
  }

  destroy() {
    this.redrawDebounce && clearTimeout(this.redrawDebounce);
    this.polyline.off('mousedown', this.handleMouseDown);
    this.polyline2.off('mousedown', this.handleMouseDown);
    this.polyline.off('click', this.handleMouseDown);
    this.polyline2.off('click', this.handleMouseDown);

    this.map.off('click', this.handleMapClick);
    this.map.off('mousemove', this.handleMapMouseMove);
    this.map.off('mousedown', this.handleMapMouseDown);

    this.onChangeHandler = undefined;
    this.onSaveHandler = undefined;
    this.onStateChangeHandler = undefined;

    this.markers = [];
    this.isDrawing = false;
    this.isFromEnd = true;
    this.isLastOnLine = false;

    this.markersGroup.clearLayers();
    this.polylineGroup.clearLayers();
    this.measuresGroup.clearLayers();

    this.map.removeLayer(this.markersGroup);
    this.map.removeLayer(this.polylineGroup);
    this.map.removeLayer(this.measuresGroup);
    this.markersGroup.remove();
    this.polylineGroup.remove();
    this.measuresGroup.remove();
    this.ticks.destroy();
    L.DomUtil.removeClass(this.getMapContainerNode(), mapClassName);
  }

  private getMapContainerNode = (): HTMLElement => {
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    return this.map._container;
  };

  private setState(state: XneekPolylineEditorState) {
    this.state = state;

    const container = this.getMapContainerNode();
    if (
      this.state === XneekPolylineEditorState.Started ||
      this.state === XneekPolylineEditorState.Drawing
    ) {
      L.DomUtil.addClass(container, styles.mapEditable);
    } else {
      L.DomUtil.removeClass(container, styles.mapEditable);
    }

    if (this.state === XneekPolylineEditorState.Editing) {
      this.ticks.setNeedLatPoint(true);
      window.requestAnimationFrame(() => {
        this.ticks.drawMeasureTicks(this.markers.map((p) => p.getLatLng()));
      });
    }

    if (this.onStateChangeHandler) {
      this.onStateChangeHandler(state);
    }
  }

  private getMarkerIcon(marker: L.Marker): HTMLElement {
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    return marker._icon;
  }

  private redrawPolyline() {
    // дешовая операция, просто утановка координат существующих линий
    this.polyline.setLatLngs(this.markers.map((p) => p.getLatLng()));
    this.polyline2.setLatLngs(this.markers.map((p) => p.getLatLng()));

    this.redrawDebounce && clearTimeout(this.redrawDebounce);
    this.redrawDebounce = setTimeout(() => {
      //console.time('markStartAndEnd')
      this.markers.forEach((point, i, arr) => {
        const icon = this.getMarkerIcon(point);

        i > 0 && i === arr.length - 1
          ? L.DomUtil.addClass(icon, styles.markerEnd)
          : L.DomUtil.removeClass(icon, styles.markerEnd);
        i === 0
          ? L.DomUtil.addClass(icon, styles.markerStart)
          : L.DomUtil.removeClass(icon, styles.markerStart);
      });
      //console.timeEnd('markStartAndEnd');
    }, 100);

    window.requestAnimationFrame(() => {
      this.markers.length > 1 &&
        this.ticks.drawMeasureTicks(this.markers.map((p) => p.getLatLng()));
    });
  }

  private removeMarker(marker: L.Marker) {
    const pointIndex = this.markers.findIndex((p) => p === marker);

    if (pointIndex === -1) {
      console.warn('Point not fount in line', { pointIndex, points: this.markers });
      return;
    }

    // console.log('marker dbl clicked'+afterIndex, e, );

    this.markers.splice(pointIndex, 1);
    this.markersGroup.removeLayer(marker);
    marker.remove();
    this.redrawPolyline();
    this.hasChanges = true;
    this.handleChange(marker, pointIndex, 'removeMarker');
  }

  private handleChange(marker: L.Marker, index: number, reason: string) {
    const points = this.markers.map((p) => p.getLatLng());
    const distance = this.ticks.distance;

    if (this.asyncPointUpdater) {
      this.asyncPointUpdaterTimeout && clearTimeout(this.asyncPointUpdaterTimeout);

      const icon1 = this.getMarkerIcon(marker);
      icon1 && L.DomUtil.addClass(icon1, styles.markerLoading);

      this.asyncPointUpdaterTimeout = setTimeout(async () => {
        const updatedLatLng = await this.asyncPointUpdater?.(
          this.markers.map((p) => p.getLatLng()),
        );
        this.onChangeHandler &&
          updatedLatLng &&
          this.onChangeHandler({
            points: updatedLatLng,
            marker,
            distance: this.ticks.distance,
            index,
            reason,
          });
        this.markers.forEach((m) => {
          L.DomUtil.removeClass(this.getMarkerIcon(m), styles.markerLoading);
        });

        this.asyncPointUpdaterTimeout = null;
      }, this.asyncPointDebounce);
    } else {
      if (this.onChangeHandler) {
        this.onChangeHandler({ points, marker, distance, index, reason });
      }
    }
  }

  private addMarker(
    latlng: L.LatLng,
    afterIndex: number | null = null,
    fromEnd = true, // признак добавлени в конец или в начало (нужно запускатьререндер не откладывая)
  ) {
    const icon = L.divIcon({
      html:
        '<div class="' +
        styles.customDrawMarker +
        '" style="color:' +
        this.polyline.options.color +
        '"></div>',
      className: styles.customDrawMarkerWrapper,
    });

    const marker = L.marker(latlng, { draggable: true, icon });

    marker.on('click', (e: L.LeafletMouseEvent) => {
      L.DomEvent.stopPropagation(e);

      if (marker === this.markers[this.markers.length - 1] || marker === this.markers[0]) {
        if (this.isDrawing) {
          this.isDrawing = false;
          this.potentialPolyline.setLatLngs([]);
          this.polylineGroup.removeLayer(this.potentialPolyline);
          this.setState(XneekPolylineEditorState.Editing);
        } else {
          this.isDrawing = true;
          this.isFromEnd = marker !== this.markers[0];
          this.polylineGroup.addLayer(this.potentialPolyline);
          this.setState(XneekPolylineEditorState.Drawing);
        }
      }
    });

    if (fromEnd) {
      // вешаем обработчик даблклика отложено чтобы не удалять при рисовании
      setTimeout(() => {
        marker.on('dblclick', (e: L.LeafletMouseEvent) => {
          L.DomEvent.stopPropagation(e);
          this.removeMarker(marker);
        });
      }, 600);
    } else {
      marker.on('dblclick', (e: L.LeafletMouseEvent) => {
        L.DomEvent.stopPropagation(e);
        this.removeMarker(marker);
      });
    }

    marker.on('dragstart', (e: L.LeafletEvent) => {
      L.DomEvent.stopPropagation(e);
      const pointIndex = this.markers.findIndex((p) => p === marker);

      console.info('pointIndex', pointIndex, 'of', this.markers.length);

      if (pointIndex === -1) {
        console.warn('Point not fount in line dragstart', { pointIndex, points: this.markers });
        return;
      }

      const handleDrag = async (ev: L.LeafletEvent) => {
        L.DomEvent.stopPropagation(ev);
        this.redrawPolyline();
        this.hasChanges = true;

        this.handleChange(marker, pointIndex, 'handleDrag');
      };

      marker.on('drag', handleDrag);

      marker.on('dragstop', (el: L.LeafletEvent) => {
        L.DomEvent.stopPropagation(el);
        marker.off('drag', handleDrag);
      });
    });

    marker.on('contextmenu', (e: L.LeafletEvent) => {
      if (this.onPointContextmenuHandler) {
        L.DomEvent.stopPropagation(e);
        this.onPointContextmenuHandler(e, {
          remove: () => this.removeMarker(marker),
          setLatLng: (latLon: L.LatLng) => {
            marker.setLatLng(latLon);
            this.redrawPolyline();
            this.hasChanges = true;
            const pointIndex = this.markers.findIndex((p) => p === marker);

            this.handleChange(marker, pointIndex, 'handleDrag');
          },
        });
      }
    });

    marker.addTo(this.markersGroup);

    if (afterIndex == null) {
      this.markers.push(marker);
    } else {
      this.markers.splice(afterIndex, 0, marker);
    }

    fromEnd && this.redrawPolyline();

    if (fromEnd) {
      this.hasChanges = true;
      this.handleChange(marker, afterIndex ?? this.markers.length, 'addMarker');
    }

    this.potentialPolyline.setLatLngs([]);
    this.ticks.clearPotential();

    return marker;
  }

  private isPointBetweenTwoAnother(targetPoint: L.LatLng, aPoint: L.LatLng, bPoint: L.LatLng) {
    const t = this.map.latLngToContainerPoint(targetPoint);
    const p1 = this.map.latLngToContainerPoint(aPoint);
    const p2 = this.map.latLngToContainerPoint(bPoint);

    const distance = distanceFromPointToLine(t, p1, p2);
    const threshold = (this.polyline2.options.weight || 10) / 2; // Половина толщины вспомогательной линии

    return distance <= threshold;
  }

  private handleMouseDown = (e: L.LeafletMouseEvent) => {
    const targetPoint = e.latlng;

    // console.time('FindPlace');
    const ind = this.markers.findIndex(
      (p, i, all) =>
        all[i + 1] &&
        this.isPointBetweenTwoAnother(targetPoint, p.getLatLng(), all[i + 1].getLatLng()),
    );
    if (ind === -1) {
      console.warn(`No line found for point ${targetPoint}`, this.markers);
      return;
    }
    // console.info('FindPlace', ind)
    // console.timeEnd('FindPlace');

    const newMarker = this.addMarker(e.latlng, ind + 1);

    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    //@ts-ignore
    //if (L.Draggable._dragging) { L.Draggable._dragging.finishDrag();}

    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    //@ts-ignore
    newMarker.dragging._draggable._onDown(e.originalEvent);
  };

  handleMapClick = (e: L.LeafletMouseEvent) => {
    const targetEl = e.originalEvent.srcElement;
    if (targetEl && !(targetEl as HTMLElement).classList.contains(mapClassName)) {
      return; // Все что не непсредствено на карту отбрасываем
    }

    if (!this.isDrawing && !this.isLastOnLine) {
      this.save();
      return;
    }

    if (this.isLastOnLine) return console.warn('line clicked');

    this.addMarker(e.latlng, this.isFromEnd ? null : 0);
    this.setState(XneekPolylineEditorState.Drawing);
  };

  handleMapMouseMove = (e: L.LeafletMouseEvent) => {
    if (!this.isDrawing) return;
    if (this.markers.length) {
      const from = L.latLng(this.markers[this.isFromEnd ? this.markers.length - 1 : 0].getLatLng());
      this.potentialPolyline.setLatLngs([from, [e.latlng.lat, e.latlng.lng]]);
      this.potentialPolyline.setStyle(this.options.drawingLineOptions);

      window.requestAnimationFrame(() => e.latlng && this.ticks.drawPotential(e.latlng, from));
    }
  };

  handleMapMouseDown = (e: L.LeafletMouseEvent) => {
    const targetEl = e.originalEvent.srcElement;
    if (targetEl) {
      this.isLastOnLine = (targetEl as HTMLElement).classList.contains(auxiliaryLineClassName);
    }
  };

  onChange(cb: typeof this.onChangeHandler) {
    this.onChangeHandler = cb;
  }

  onSave(cb: typeof this.onSaveHandler) {
    this.onSaveHandler = cb;
  }

  onStateChange(cb: typeof this.onStateChangeHandler) {
    this.onStateChangeHandler = cb;
  }
  onPointContextmenu(cb: typeof this.onPointContextmenuHandler) {
    this.onPointContextmenuHandler = cb;
  }
  startEdit(points: Array<L.LatLng> = [], options?: L.PolylineOptions, _stayInDrawing = false) {
    this.save();
    this.destroy();
    this.markers = [];
    this.polyline.setLatLngs([]);
    this.polyline2.setLatLngs([]);
    this.potentialPolyline.setLatLngs([]);

    options && this.setLineOptions(options);

    // Start editing polyline on map

    this.isDrawing = true;
    this.setState(XneekPolylineEditorState.Started);
    this.init();

    if (points.length) {
      points.forEach((latLng, i, all) => {
        this.addMarker(L.latLng(latLng), null, i === all.length - 1);
      });

      if (points.length > 1) {
        this.isDrawing = false;
        this.setState(XneekPolylineEditorState.Editing);
      }
    }
  }

  setLineOptions(options: L.PolylineOptions) {
    const weight =
      options.weight ??
      this.polyline.options.weight ??
      this.options.mainLineOptions.weight ??
      defaultOptions.mainLineOptions.weight ??
      2;

    const mainLineOptions = {
      ...defaultOptions.mainLineOptions,
      ...this.options.mainLineOptions,
      ...this.polyline.options,
      ...options,
    };
    this.polyline.setStyle(mainLineOptions);
    this.options.mainLineOptions = mainLineOptions;

    if (options.weight) {
      const auxiliaryLineOptions = {
        ...defaultOptions.auxiliaryLineOptions,
        ...this.options.auxiliaryLineOptions,
        ...this.polyline2.options,
        weight: weight * 4 < 16 ? 16 : weight * 4,
      };
      this.polyline2.setStyle(auxiliaryLineOptions);
      this.options.auxiliaryLineOptions = auxiliaryLineOptions;
    }

    //
    const drawingLineOptions = {
      ...defaultOptions.drawingLineOptions,
      ...this.options.drawingLineOptions,
      ...this.potentialPolyline.options,
      ...options,
      dashArray: [weight + 5, weight + 7],
    };
    this.options.drawingLineOptions = drawingLineOptions;
    if (this.potentialPolyline.getBounds().isValid()) {
      this.potentialPolyline.setStyle(drawingLineOptions);
    }

    if (options?.color) {
      this.ticks.setColor(options.color ?? defaultOptions.mainLineOptions.color);
      this.markersGroup.eachLayer((l) => {
        const el = (l as L.Marker).getElement()?.childNodes[0] as HTMLDivElement;
        if (el) {
          el.style.color = options.color ?? defaultOptions.mainLineOptions.color ?? 'red';
        }
      });
    }
  }

  save() {
    if (this.asyncPointUpdaterTimeout) {
      console.warn('HAS UNSAVED CHANGES');
      return;
    }

    this.hasChanges = false;

    if (this.onSaveHandler) {
      this.onSaveHandler(
        this.markers.map((p) => p.getLatLng()),
        this.ticks.distance,
      );
    }
    this.stopEdit();
  }

  stopEdit(_withSave = false) {
    this.isDrawing = false;

    this.setState(XneekPolylineEditorState.Idle);
    this.destroy();
  }

  public setStartDistance = (distance = 0) => {
    this.ticks.setStartDistance(distance);
  };

  public getHasChanges = () => {
    return this.hasChanges;
  };

  setAsyncPointUpdater(updater: typeof this.asyncPointUpdater) {
    this.asyncPointUpdater = updater;
  }

  setAsyncPointDebounce(time?: number) {
    this.asyncPointDebounce = time;
  }

  //
}

let instance: XneekPolylineEditor | null = null;

export const getXneekPolylineEditorSingletone = (
  map: L.Map,
  options: Partial<IXneekPolylineEditorOptions> = {},
) => {
  if (instance) return instance;
  instance = new XneekPolylineEditor(map, options);
  return instance;
};
