import { IRouteObject } from '@apps/Routes/@types/routes.types';
import PohList from '@ui-kit/List';
import { showModal } from '@ui-kit/Modal';

import RoutesEditorListItem from '../RoutesEditorSidebar/RoutesEditorListItem';

interface IRouteObjectSelectModalProps {
  routeObjects: IRouteObject[];
  onSelect: (ro: IRouteObject) => void;
}

const RouteObjectSelectModal = ({ routeObjects, onSelect }: IRouteObjectSelectModalProps) => {
  return (
    <div style={{ overflowY: 'auto', minWidth: 400, maxHeight: 300 }}>
      <PohList
        flush
        data={routeObjects.map((routeObject) => {
          return {
            className: 'p-0',
            //action: true,
            key: routeObject.id,
            content: <RoutesEditorListItem routeObject={routeObject} />,
            onClick: (e: React.MouseEvent) => {
              e.preventDefault();
              onSelect(routeObject);
            },
          };
        })}
      />
    </div>
  );
};

export function selectRouteObjectFromListAsync({
  routeObjects,
  title = 'Выбор объекта маршрута',
}: {
  routeObjects: IRouteObject[];
  title?: string;
}): Promise<IRouteObject> {
  return new Promise((resolve) => {
    showModal({
      size: 'sm',
      title: title,
      children: (closeHandler: () => void) => (
        <RouteObjectSelectModal
          routeObjects={routeObjects}
          onSelect={(s) => {
            resolve(s);
            closeHandler();
          }}
        />
      ),
    });
  });
}
