import { configureStore } from '@reduxjs/toolkit';

import routeReducer from './route.slice';

export const routesStore = configureStore({
  reducer: {
    route: routeReducer,
  },
  middleware: (getDefaultMiddleware) =>
    getDefaultMiddleware({
      serializableCheck: {
        ignoredPaths: ['route.routeInfo.dateCreate'],
      },
    }),
});

export type RoutesState = ReturnType<typeof routesStore.getState>;
export type RoutesDispatch = typeof routesStore.dispatch;
