import { useDispatch, useSelector } from 'react-redux';
import type { TypedUseSelectorHook } from 'react-redux';

import type { RoutesDispatch, RoutesState } from './store';

// Use throughout your app instead of plain `useDispatch` and `useSelector`
export const useRoutesDispatch: () => RoutesDispatch = useDispatch;
export const useRoutesSelector: TypedUseSelectorHook<RoutesState> = useSelector;
