import React from 'react';

import clsx from 'clsx';
import * as L from 'leaflet';

import { reorderRouteObjectsAsync } from '@apps/Routes/@services/routes.service';
import { round } from '@helpers/mathHelper';
import notificationHelper, { success } from '@helpers/notificationHelper';
import PohAlert from '@ui-kit/Alert';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';

import RoutesEditorListItem from './RoutesEditorListItem';
import styles from './styles.module.less';
import { deleteRouteObjectWithConfirm } from '../../../@helpers/delete.helper';
import { downloadGpx } from '../../../@helpers/gpx.helper';
import { getLeafletMapManager } from '../../../@managers/leafletMap.manager';
import { useRoutesDispatch, useRoutesSelector } from '../../../@store/hooks';
import {
  setActiveRouteObject,
  setActiveRouteObjectById,
  setCurrentRouteObject,
  setRouteObjects,
} from '../../../@store/route.slice';
import {
  addRouteObject,
  deleteRouteObject,
  getRouteObjectsData,
  updateRouteLine,
  updateRoutePoint,
} from '../../../@store/route.thunk';
import {
  IBaseRouteObjectLine,
  IBaseRouteObjectPoint,
  IRouteObject,
  RouteObjectType,
} from '../../../@types/routes.types';
import { importGpxModal } from '../ImportGPX';
import { selectTrackForJoin } from '../JoinTracksModal';
import { getPointAround } from '../PointsAround';
import { getAutoRouteFromPoints } from '../RouteAuto/routesAuto.helper';
import { selectRouteObjectFromListAsync } from '../RouteObjectSelectModal';

const RoutesEditorList: React.FC<React.HTMLAttributes<HTMLDivElement>> = ({ ...rest }) => {
  const dispatch = useRoutesDispatch();

  const orderSaveDebounceRef = React.useRef<ReturnType<typeof setTimeout>>(undefined);

  const {
    isRouteObjectsLoading,
    routeObjectsError,
    routeObjects,
    routeInfo,
    activeRouteObject,
    filters,
  } = useRoutesSelector((state) => state.route);

  React.useEffect(() => {
    if (routeInfo?.id) dispatch(getRouteObjectsData(routeInfo.id));
  }, [routeInfo?.id]);

  if (isRouteObjectsLoading) {
    return (
      <div className="d-flex justify-content-center align-items-center">
        <PohLoader />
      </div>
    );
  }
  if (routeObjectsError) {
    return (
      <div>
        <PohAlert>{routeObjectsError.message}</PohAlert>
      </div>
    );
  }

  const handleDeleteRouteObject = async (routeObject: IRouteObject, withoutConfirm = false) => {
    await deleteRouteObjectWithConfirm(routeObject, withoutConfirm);
    await dispatch(deleteRouteObject(routeObject?.id)).unwrap();
    dispatch(setActiveRouteObject(null));
    dispatch(setCurrentRouteObject(null));
  };

  const handleCenterRouteObject = async (routeObject: IRouteObject, e: React.MouseEvent) => {
    if (routeObject.type === RouteObjectType.Point) {
      getLeafletMapManager().centerOnPoint(routeObject.coordinates, e.altKey);
    } else {
      getLeafletMapManager().fitBounds(routeObject.points);
    }
  };

  const handleEditRouteObject = async (routeObject: IRouteObject) => {
    dispatch(setCurrentRouteObject(routeObject));

    if (routeObject.type === RouteObjectType.Point) {
      getLeafletMapManager().startEdit(routeObject.id);
    } else {
      getLeafletMapManager().startEdit(routeObject.id);
    }
  };

  const handleActivateRouteObject = async (
    routeObject: IRouteObject,
    centred = true,
    maxZoom = false,
  ) => {
    dispatch(setActiveRouteObjectById(routeObject.id));
    if (routeObject.type === RouteObjectType.Point) {
      getLeafletMapManager().makeRouteObjectActive(routeObject.id, centred);
      maxZoom && getLeafletMapManager().centerOnPoint(routeObject.coordinates);
    } else {
      getLeafletMapManager().makeRouteObjectActive(routeObject.id, centred);
      maxZoom && getLeafletMapManager().fitBounds(routeObject.points);
    }
  };

  const handleMoveItemUp = (obj: IRouteObject) => {
    const currentRouteObjectIndex = routeObjects.findIndex((ro) => ro.id === obj.id);
    if (currentRouteObjectIndex > 0) {
      const newItems = [...routeObjects];
      const [moving] = newItems.splice(currentRouteObjectIndex, 1);
      newItems.splice(currentRouteObjectIndex - 1, 0, moving);
      dispatch(setRouteObjects(newItems.map((o, i) => ({ ...o, order: i }))));
      if (orderSaveDebounceRef.current) clearTimeout(orderSaveDebounceRef.current);
      orderSaveDebounceRef.current = setTimeout(() => {
        reorderRouteObjectsAsync(newItems.map((r) => r.id));
      }, 3000);
    }
  };

  const handleMoveItemDown = (obj: IRouteObject) => {
    const currentRouteObjectIndex = routeObjects.findIndex((ro) => ro.id === obj.id);
    if (currentRouteObjectIndex < routeObjects.length - 1) {
      const newItems = [...routeObjects];
      const moving = newItems.splice(currentRouteObjectIndex, 1);
      newItems.splice(currentRouteObjectIndex + 1, 0, ...moving);
      dispatch(setRouteObjects(newItems.map((o, i) => ({ ...o, order: i }))));
      if (orderSaveDebounceRef.current) clearTimeout(orderSaveDebounceRef.current);
      orderSaveDebounceRef.current = setTimeout(() => {
        reorderRouteObjectsAsync(newItems.map((r) => r.id));
      }, 3000);
    }
  };

  React.useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!activeRouteObject) return;

      if (['Backspace', 'Delete'].includes(e.key)) {
        handleDeleteRouteObject(activeRouteObject);
      }
      if (['ArrowUp', 'ArrowDown'].includes(e.key)) {
        e.preventDefault();
        const currentRouteObjectIndex = routeObjects.findIndex(
          (ro) => ro.id === activeRouteObject.id,
        );

        if (e.altKey) {
          if (e.key === 'ArrowUp') handleMoveItemUp(activeRouteObject);
          if (e.key === 'ArrowDown') handleMoveItemDown(activeRouteObject);
        } else {
          const anotherRouteObject =
            e.key === 'ArrowUp'
              ? (routeObjects?.[currentRouteObjectIndex - 1] ??
                routeObjects?.[routeObjects.length - 1] ??
                routeObjects[0])
              : (routeObjects?.[currentRouteObjectIndex + 1] ?? routeObjects[0]);

          handleActivateRouteObject(anotherRouteObject, e.shiftKey, e.ctrlKey);
        }
      }

      if (e.key === 'Enter') {
        handleEditRouteObject(activeRouteObject);
      }
    };

    if (activeRouteObject) {
      document.addEventListener('keydown', handleKeyDown);
    }

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [activeRouteObject, routeObjects]);

  const preparedRoutesObjects: IRouteObject[] = routeObjects
    .toSorted((a, b) => a.order - b.order)
    .filter((ro) => {
      const valid = filters.showNotInDistance || ro.is_in_distance;

      if (filters.showLines && ro.type === RouteObjectType.Line && valid) return true;
      if (filters.showPoints && ro.type === RouteObjectType.Point && valid) return true;

      return false;
    });

  return (
    <div
      {...rest}
      className={clsx('d-flex flex-column h-100 flex-grow-1', styles.listObjects, rest.className)}
    >
      {!routeObjects.length && (
        <div className="p-3 vertical-gapped">
          <p className="text-muted">Здесь будут треки и точки вашего маршрута</p>

          <PohButton
            variant={ButtonVariant.OutlinePrimary}
            onClick={() => getLeafletMapManager().startNewLine()}
            block
          >
            Нарисовать трек
          </PohButton>
          <PohButton
            variant={ButtonVariant.OutlinePrimary}
            onClick={() => getLeafletMapManager().startNewPoint()}
            block
          >
            Нарисовать точку
          </PohButton>
          <PohButton
            variant={ButtonVariant.Primary}
            onClick={() =>
              importGpxModal().then((results) => {
                for (const res of results) {
                  dispatch(
                    addRouteObject({ layer: res.layer, name: res.name, cb: () => {} }),
                  ).unwrap();
                }
              })
            }
            block
          >
            Импорт из GPX
          </PohButton>
        </div>
      )}
      <PohList
        flush
        data={preparedRoutesObjects.map((routeObject) => {
          const menuActions: Record<string, (e: React.MouseEvent) => void> = {
            'Редактировать (2x-click)': () => handleEditRouteObject(routeObject),
            'Центрировать на карте (alt+click)': (e) => handleCenterRouteObject(routeObject, e),
            '----': () => {},
            'Поднять выше [Alt + ↑]': () => handleMoveItemUp(routeObject),
            'Опустить ниже [Alt + ↓]': () => handleMoveItemDown(routeObject),
          };

          if (routeObject.type === RouteObjectType.Line) {
            Object.assign(menuActions, {
              '-----': () => {},
              'Развернуть трек': async () => {
                getLeafletMapManager().startLoadingForCurrent();
                await dispatch(
                  updateRouteLine({
                    line: {
                      ...routeObject,
                      points: [...routeObject.points].reverse(),
                    },
                    hasCoordinatesChanges: false,
                  }),
                ).unwrap();
                getLeafletMapManager().stopLoadingForCurrent();
              },
              'Объединить с другим': async () => {
                const trackForJoin = await selectTrackForJoin({
                  currentLine: routeObject,
                  anotherLines: routeObjects.filter(
                    (r) => r.type === RouteObjectType.Line && r.id !== routeObject.id,
                  ) as IBaseRouteObjectLine[],
                });
                const newPoints = [...routeObject.points, ...trackForJoin.points];
                getLeafletMapManager().startLoadingForCurrent();
                getLeafletMapManager().getLineById(routeObject.id)?.setLatLngs(newPoints);
                await dispatch(
                  updateRouteLine({
                    line: {
                      ...routeObject,
                      name: [routeObject.name, trackForJoin.name].join(' + '),
                      description: [routeObject.description, trackForJoin.description].join('\n'),
                      distance: routeObject.distance + trackForJoin.distance,
                      points: newPoints,
                    },
                    hasCoordinatesChanges: false,
                  }),
                ).unwrap();
                handleDeleteRouteObject(trackForJoin, true);
                getLeafletMapManager().getLineById(routeObject.id)?.setLatLngs(newPoints);
                getLeafletMapManager().stopLoadingForCurrent();
                notificationHelper.success('Готово');
              },
              'Обновить данные о высотах': async () => {
                getLeafletMapManager().startLoadingForCurrent();
                await dispatch(
                  updateRouteLine({
                    line: {
                      ...routeObject,
                    },
                    hasCoordinatesChanges: true,
                  }),
                ).unwrap();
                getLeafletMapManager().stopLoadingForCurrent();
              },
              'Добавить точку в начале трека': () => {
                const firstPoint = routeObject.points[0];
                getLeafletMapManager().startNewPoint(
                  new L.LatLng(firstPoint[0], firstPoint[1], firstPoint?.[2]),
                );
              },
              'Добавить точку в конце трека': () => {
                const lastPoint = routeObject.points[routeObject.points.length - 1];

                getLeafletMapManager().startNewPoint(
                  new L.LatLng(lastPoint[0], lastPoint[1], lastPoint?.[2]),
                );
              },
              'Привязать начало трека к точке': async () => {
                getLeafletMapManager().startLoadingForCurrent();
                const selectedPoint = (await selectRouteObjectFromListAsync({
                  routeObjects: preparedRoutesObjects.filter(
                    (x) => x.type === RouteObjectType.Point,
                  ),
                  title: 'Выберите точку для привязки начала трека',
                })) as IBaseRouteObjectPoint;
                await dispatch(
                  updateRouteLine({
                    line: {
                      ...routeObject,
                      points: [selectedPoint.coordinates, ...routeObject.points.slice(1)],
                    },
                    hasCoordinatesChanges: false,
                  }),
                ).unwrap();
                notificationHelper.success(
                  `Начало трека привязано к точке "${selectedPoint.name}"`,
                );
                getLeafletMapManager().stopLoadingForCurrent();
              },
              'Привязать конец трека к точке': async () => {
                getLeafletMapManager().startLoadingForCurrent();
                const selectedPoint = (await selectRouteObjectFromListAsync({
                  routeObjects: preparedRoutesObjects.filter(
                    (x) => x.type === RouteObjectType.Point,
                  ),
                  title: 'Выберите точку для привязки конца трека',
                })) as IBaseRouteObjectPoint;
                await dispatch(
                  updateRouteLine({
                    line: {
                      ...routeObject,
                      points: [...routeObject.points.slice(0, -1), selectedPoint.coordinates],
                    },
                    hasCoordinatesChanges: false,
                  }),
                ).unwrap();
                notificationHelper.success(`Конец трека привязан к точке "${selectedPoint.name}"`);
                getLeafletMapManager().stopLoadingForCurrent();
              },
              '-------': () => {},
              'Скачать GPX': (e: MouseEvent) => {
                downloadGpx(
                  [
                    {
                      name: routeObject.name,
                      description: routeObject.description,
                      coordinates: routeObject.points,
                    },
                  ],
                  [],
                  {
                    name: routeObject.name,
                    description: routeObject.description,
                    asRoute: e.ctrlKey,
                  },
                );
              },
            });
            routeObject.points.length <= 5 &&
              Object.assign(menuActions, {
                'Проложить маршрут': async () => {
                  getAutoRouteFromPoints({
                    points: routeObject.points,
                    onSave: async (newPoints) => {
                      getLeafletMapManager().startLoadingForCurrent();
                      getLeafletMapManager().getLineById(routeObject.id)?.setLatLngs(newPoints);
                      await dispatch(
                        updateRouteLine({
                          line: {
                            ...routeObject,
                            points: newPoints,
                          },
                          hasCoordinatesChanges: false,
                        }),
                      ).unwrap();
                      getLeafletMapManager().getLineById(routeObject.id)?.setLatLngs(newPoints);
                      getLeafletMapManager().stopLoadingForCurrent();
                      notificationHelper.success('Готово');
                    },
                  });
                },
              });
          }

          if (routeObject.type === RouteObjectType.Point) {
            Object.assign(menuActions, {
              '------': () => {},
              'Обновить данные о высоте': async () => {
                getLeafletMapManager().startLoadingForCurrent();
                await dispatch(
                  updateRoutePoint({
                    point: {
                      ...routeObject,
                    },
                    hasCoordinatesChanges: true,
                  }),
                ).unwrap();
                getLeafletMapManager().stopLoadingForCurrent();
              },
              'Начать трек в этой точке': () => {
                const firstPoint = routeObject.coordinates;
                const ll = new L.LatLng(firstPoint[0], firstPoint[1], firstPoint?.[2]);
                getLeafletMapManager().startNewLine([ll]);
              },
              '-------': () => {},
              'Скачать точку как GPX': (e: MouseEvent) => {
                downloadGpx(
                  [],
                  [
                    {
                      name: routeObject.name,
                      description: routeObject.description,
                      coordinate: routeObject.coordinates,
                    },
                  ],
                  {
                    name: routeObject.name,
                    description: routeObject.description,
                    asRoute: e.ctrlKey,
                  },
                );
              },
              'Привязать к ближайшей POI': async (ev: MouseEvent) => {
                ev.stopPropagation();
                const latLng: L.LatLng | undefined = new L.LatLng(
                  routeObject.coordinates[0],
                  routeObject.coordinates[1],
                );

                if (latLng) {
                  const po = await getPointAround(latLng.lat, latLng.lng);
                  if (po) {
                    getLeafletMapManager().startLoadingForCurrent();
                    getLeafletMapManager()
                      .getPointById(routeObject.id)
                      ?.setLatLng(new L.LatLng(po.lat, po.lon));
                    await dispatch(
                      updateRoutePoint({
                        point: {
                          ...routeObject,
                          coordinates: [po.lat, po.lon],
                        },
                        hasCoordinatesChanges: true,
                      }),
                    ).unwrap();
                    success(`Установлены координаты точки ${po.name}`);
                    getLeafletMapManager().stopLoadingForCurrent();
                    getLeafletMapManager().completeEdit(routeObject.id);
                  }
                }
              },
              'Показать координаты': () => {
                confirmModal2(
                  routeObject.coordinates
                    .slice(0, 2)
                    .map((z) => round(z, 5))
                    .join(', '),
                );
              },
            });
          }

          Object.assign(menuActions, {
            '---': () => {},
            'Удалить [del]': () => handleDeleteRouteObject(routeObject),
          });

          return {
            className: 'p-0',
            //action: true,
            key: routeObject.id,
            content: <RoutesEditorListItem routeObject={routeObject} menuActions={menuActions} />,
            active: !!(activeRouteObject && activeRouteObject.id === routeObject.id),
            onClick: (e: React.MouseEvent) => {
              e.preventDefault();
              handleActivateRouteObject(routeObject, e.shiftKey, e.altKey);
            },
            onDoubleClick: (e: React.MouseEvent) => {
              e.preventDefault();
              handleActivateRouteObject(routeObject, true, true);
              handleEditRouteObject(routeObject);
            },
          };
        })}
      />
    </div>
  );
};

export default RoutesEditorList;
