import React, { FormEvent } from 'react';

import X from '@pohodnik/icons/svg/Signs/X';
import L from 'leaflet';

import PohButton, { ButtonSize } from '@ui-kit/Button';
import PohInput, { InputSizes } from '@ui-kit/Input';
import PohList from '@ui-kit/List';

import { getLeafletMapManager } from '../../../@managers/leafletMap.manager';
import { findPoint, IFindPointResult } from '../../../@services/routes.service';
import { useRoutesDispatch, useRoutesSelector } from '../../../@store/hooks';
import { setIsSearchOpen } from '../../../@store/route.slice';

interface IRoutesEditorSearch {}
const RoutesEditorSearch: React.FC<IRoutesEditorSearch> = () => {
  const dispatch = useRoutesDispatch();

  const [isLoading, setIsLoading] = React.useState(false);
  const [results, setResults] = React.useState<IFindPointResult[]>([]);

  const { isSearchOpen } = useRoutesSelector((state) => state.route);

  const formRef = React.useRef<HTMLFormElement>(null);

  if (!isSearchOpen) return null;

  const handlerSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setResults([]);
    const searchString = (
      ((e.target as HTMLFormElement).elements as any).search as HTMLInputElement
    ).value;
    const res = await findPoint(searchString);
    setResults(res);
    setIsLoading(false);
  };

  const handleCancel = () => {
    dispatch(setIsSearchOpen(false));
  };

  return (
    <div>
      <header className="d-flex align-items-center justify-content-between px-3 py-2 bg-light">
        <strong>Поиск</strong>
        <PohButton
          size={ButtonSize.Small}
          className="flex-shrink-0"
          icon={true}
          onClick={handleCancel}
        >
          <X />
        </PohButton>
      </header>
      <form className="m-0 p-0" onSubmit={handlerSubmit} ref={formRef}>
        <div className="p-2 d-flex">
          <PohInput
            placeholder="Поиск"
            size={InputSizes.Small}
            required
            disabled={isLoading}
            defaultValue=""
            autoFocus
            labelClassName="text-muted"
            name="search"
          />{' '}
        </div>
      </form>
      <PohList
        flush
        data={results.map((r) => {
          return {
            key: r.place_id,
            children: (
              <>
                {r.name}
                <br />
                <small className="text-muted text-truncate">{r.display_name}</small>
              </>
            ),
            onClick: () => {
              const point = new L.LatLng(+r.lat, +r.lon);
              getLeafletMapManager().startNewPoint(point);
              getLeafletMapManager().centerOnPoint(point);
              dispatch(setIsSearchOpen(false));
            },
            action: true,
          };
        })}
      />
    </div>
  );
};

export default RoutesEditorSearch;
