import React, { FormEvent } from 'react';

import X from '@pohodnik/icons/svg/Signs/X';

import { selectUserAsync } from '@components/UserSelector/userSelectHelper';
import PohAva from '@ui-kit/Ava';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohList from '@ui-kit/List';

import {
  addRouteAccessData,
  AllowMapParamsForSave,
  deleteRouteAccessData,
  getRouteAccessData,
  IRouteAccessData,
  saveMapParamAsync,
} from '../../../@services/routes.service';
import { useRoutesDispatch, useRoutesSelector } from '../../../@store/hooks';
import {
  setIsAccessParamsEditorOpen,
  setIsBaseParamsEditorOpen,
  updateRouteInfo,
} from '../../../@store/route.slice';
import { IBaseRoute } from '../../../@types/routes.types';

const RoutesEditorAccess: React.FC = () => {
  const dispatch = useRoutesDispatch();

  const [data, setData] = React.useState<IRouteAccessData[]>([]);
  const [isLoading, setIsLoading] = React.useState(false);

  const { isAccessParamsEditorOpen, routeInfo } = useRoutesSelector((state) => state.route);

  const formRef = React.useRef<HTMLFormElement>(null);

  React.useEffect(() => {
    if (!routeInfo?.id) return;
    getRouteAccessData(routeInfo.id).then(setData);
  }, [routeInfo?.id]);

  if (!isAccessParamsEditorOpen || !routeInfo) return null;

  const handlerSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    const formData = new FormData(e.target as HTMLFormElement);
    const formDataObj: Record<string, any> = {};
    formData.forEach((value, key) => (formDataObj[key] = value));
    const tasks: Promise<any>[] = [];

    Object.entries(formDataObj).map(([key, value]) => {
      if (routeInfo[key as keyof IBaseRoute] !== value) {
        tasks.push(
          saveMapParamAsync(
            routeInfo.id,
            key === 'description' ? 'desc' : (key as AllowMapParamsForSave),
            value,
          ),
        );
      }
    });
    await Promise.all(tasks);
    setIsLoading(false);
    dispatch(updateRouteInfo({ ...routeInfo, ...formDataObj }));
    dispatch(setIsBaseParamsEditorOpen(false));
  };

  const handleCancel = () => {
    dispatch(setIsAccessParamsEditorOpen(false));
  };

  if (isLoading) return null;

  return (
    <form className="m-0 p-0" onSubmit={handlerSubmit} ref={formRef}>
      <header className="d-flex align-items-center justify-content-between px-3 py-2 bg-light">
        <strong>Редактирование прав доступа</strong>
        <PohButton
          size={ButtonSize.Small}
          className="flex-shrink-0"
          icon={true}
          onClick={handleCancel}
        >
          <X />
        </PohButton>
      </header>
      <div className="px-3 py-2">
        <PohList
          data={data.map((d) => {
            return {
              key: d.id,
              children: (
                <div className="d-flex p-0 align-items-center">
                  <PohAva src={d.photo} alt={d.name} className="me-2" />
                  {d.name} {d.surname}
                  {!d.isAuthor && (
                    <PohButton
                      icon={IconsEnum.trash}
                      className="ms-auto"
                      onClick={async () => {
                        await deleteRouteAccessData(d.id);
                        setData((cur) => cur.filter((c) => c.id !== d.id));
                      }}
                    />
                  )}
                </div>
              ),
            };
          })}
        />
      </div>
      <div className="p-2">
        <PohButton
          block
          onClick={async () => {
            const user = await selectUserAsync({ excludeIds: data.map((u) => u.idUser) });
            const id = await addRouteAccessData(routeInfo.id, user.id);
            setData((cur) => [
              ...cur,
              {
                ...user,
                idUser: user.id,
                id,
                isAuthor: false,
              },
            ]);
          }}
        >
          Добавить
        </PohButton>
      </div>
    </form>
  );
};

export default RoutesEditorAccess;
