import React from 'react';

import * as L from 'leaflet';

import { getMap } from '@helpers/leafletHelper';
import { uploadBase64Async } from '@ui-kit/ImageUploader/service';

import { TEMPORARY_LINE_DASH_ARRAY } from '../../../@const/routeObjects.const';
import { saveMapParamAsync } from '../../../@services/routes.service';
import { useRoutesSelector } from '../../../@store/hooks';
import { RouteObjectType } from '../../../@types/routes.types';

const MapPreviewUpdater: React.FC<{ onComplete: (url: string) => void }> = ({ onComplete }) => {
  const { routeObjects, routeInfo, currentMapType } = useRoutesSelector((state) => state.route);

  const ref = React.useRef<HTMLDivElement>(null);
  const mapRef = React.useRef<L.Map>(null);

  React.useEffect(() => {
    if (!ref.current || !currentMapType || !routeInfo?.id) return;
    if (!mapRef.current) {
      mapRef.current = getMap(ref.current as HTMLElement, {
        preferCanvas: true,
        zoomControl: false,
        dragging: false,
        touchZoom: false,
      });
    }

    const map = mapRef.current;

    L.tileLayer(currentMapType?.tileUrlTmpl, {
      ...currentMapType,
      id: currentMapType.id.toString(),
    }).addTo(map);

    const boundCoordinates: L.LatLngExpression[] = [];
    routeObjects.forEach((ro) => {
      if (ro.type === RouteObjectType.Line) {
        const pl = new L.Polyline(ro.points, {
          color: ro.color,

          weight: ro.width,
          opacity: ro.opacity / 100,
          dashArray: ro.is_in_distance ? undefined : TEMPORARY_LINE_DASH_ARRAY,
        });

        pl.addTo(map);
        boundCoordinates.push(...ro.points);
      } else {
        // const marker = L.marker(ro.coordinates, { icon: getDivIcon() })
        // setMarkerStyles(
        //   marker,
        //   {
        //     color: ro.color,
        //     opacity: ro.is_in_distance ? 1 : TEMPORARY_POINT_OPACITY
        //   }
        // );
        // marker.addTo(map)
      }
    });

    const bounds = new L.LatLngBounds(boundCoordinates);
    if (bounds.isValid()) map.fitBounds(bounds);

    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    //@ts-expect-error
    import('leaflet-image').then((module) => {
      module.default(map, (_: Error, canvas: HTMLCanvasElement) => {
        uploadBase64Async(canvas.toDataURL(), {
          folder: 'images/routes_preview/',
          name: `route${routeInfo?.id}preview`,
        }).then((res) => {
          saveMapParamAsync(routeInfo?.id, 'preview_img', res.src).then(() => {
            onComplete(res.src);
          });
        });
      });
    });
  }, [routeObjects]);

  return <div ref={ref} style={{ width: 400, height: 400, position: 'fixed', left: -9999 }}></div>;
};

export default MapPreviewUpdater;
